long long mergeCount(int arr[], int l, int m, int r) {
    int n1=m-l+1, n2=r-m;
    int L[n1], R[n2];
    for(int i=0;i<n1;i++) L[i]=arr[l+i];
    for(int j=0;j<n2;j++) R[j]=arr[m+1+j];
    long long inv=0; int i=0,j=0,k=l;
    while(i<n1&&j<n2) {
        if(L[i]<=R[j]) arr[k++]=L[i++];
        else { arr[k++]=R[j++]; inv+=n1-i; }
    }
    while(i<n1) arr[k++]=L[i++];
    while(j<n2) arr[k++]=R[j++];
    return inv;
}
long long countInversions(int arr[], int l, int r) {
    if(l>=r) return 0;
    int m=(l+r)/2;
    return countInversions(arr,l,m)+countInversions(arr,m+1,r)+mergeCount(arr,l,m,r);
}

