def closest_pair(points):
    points.sort()
    def dist(a, b): return math.sqrt((a[0]-b[0])**2 + (a[1]-b[1])**2)
    def solve(pts):
        if len(pts) <= 3:
            return min(dist(pts[i],pts[j]) for i in range(len(pts)) for j in range(i+1,len(pts)))
        mid = len(pts)//2
        d = min(solve(pts[:mid]), solve(pts[mid:]))
        strip = [p for p in pts if abs(p[0]-pts[mid][0]) < d]
        strip.sort(key=lambda p: p[1])
        for i in range(len(strip)):
            for j in range(i+1, min(i+7, len(strip))):
                d = min(d, dist(strip[i], strip[j]))
        return d
    return solve(points)

