int maxCrossingSum(int arr[], int l, int m, int h) {
    int leftSum=INT_MIN, sum=0;
    for(int i=m;i>=l;i--) { sum+=arr[i]; leftSum=max(leftSum,sum); }
    int rightSum=INT_MIN; sum=0;
    for(int i=m+1;i<=h;i++) { sum+=arr[i]; rightSum=max(rightSum,sum); }
    return leftSum+rightSum;
}
int maxSubarraySum(int arr[], int l, int h) {
    if(l==h) return arr[l];
    int m=(l+h)/2;
    return max({maxSubarraySum(arr,l,m), maxSubarraySum(arr,m+1,h), maxCrossingSum(arr,l,m,h)});
}

